<?php

declare(strict_types=1);

require_once __DIR__ . '/../bootstrap.php';
Auth::requireLogin();
$projectId = filter_var($_GET['id'] ?? null, FILTER_VALIDATE_INT);
$project = $projectId === false || $projectId === null ? null : Project::findForUser((int) $projectId, Auth::id());
if ($project === null) { http_response_code(404); exit('Project not found.'); }
$commits = GitDiffService::commits($project);
$result = null;
$from = '';
$to = '';
if (is_post()) {
    verify_csrf();
    $from = post_string('from');
    $to = post_string('to');
    $result = GitDiffService::compare($project, $from, $to);
}
$pageTitle = 'Compare changes';
$activePage = 'dashboard';
$activeProjectSection = 'review';
require __DIR__ . '/../views/header.php';
?>
<section class="app-shell narrow"><div class="breadcrumb"><a href="<?= e(url('project.php?id=' . (int) $project['id'])) ?>"><?= e($project['name']) ?></a><span>/</span><span>Compare changes</span></div><div class="project-heading compact"><div><p class="landing-kicker">Change-set review</p><h1>What did AI change?</h1><p>Choose any two commits. Git proves the file and declaration changes; authorship still remains unknown.</p></div></div><?php require __DIR__ . '/../views/project-nav.php'; ?><section class="compare-card"><?php if ($commits === []): ?><div class="empty-inline">Commit history was not available. The repository may have been cloned without accessible Git history.</div><?php else: ?><form method="post" class="compare-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label>Earlier commit<select name="from" required><option value="">Choose a commit</option><?php foreach ($commits as $commit): ?><option value="<?= e($commit['sha']) ?>" <?= $from === $commit['sha'] ? 'selected' : '' ?>><?= e(substr($commit['sha'], 0, 8) . ' - ' . $commit['message']) ?></option><?php endforeach; ?></select></label><label>Later commit<select name="to" required><option value="">Choose a commit</option><?php foreach ($commits as $commit): ?><option value="<?= e($commit['sha']) ?>" <?= $to === $commit['sha'] ? 'selected' : '' ?>><?= e(substr($commit['sha'], 0, 8) . ' - ' . $commit['message']) ?></option><?php endforeach; ?></select></label><button class="button button-primary" type="submit">Review change set</button></form><?php endif; ?><?php if ($result !== null): ?><?php if (isset($result['error'])): ?><div class="inline-error"><?= e($result['error']) ?></div><?php else: ?><article class="change-result"><h2><?= e($result['summary']) ?></h2><?php if ($result['risky'] !== []): ?><div class="risk-summary"><b>Extra review recommended</b><?php foreach ($result['risky'] as $item): ?><span><?= e($item['risk'] . ': ' . $item['path']) ?></span><?php endforeach; ?></div><?php endif; ?><section class="delta-summary"><div><strong><?= count($result['symbol_delta']['added']) ?></strong><span>symbols added</span></div><div><strong><?= count($result['symbol_delta']['removed']) ?></strong><span>symbols removed</span></div><div><strong><?= count($result['symbol_delta']['changed']) ?></strong><span>signatures changed</span></div><div><strong><?= count($result['impact']['routes']) ?></strong><span>current routes affected</span></div><div><strong><?= count($result['impact']['tables']) ?></strong><span>data symbols affected</span></div></section><?php if ($result['symbol_delta']['added'] !== [] || $result['symbol_delta']['removed'] !== [] || $result['symbol_delta']['changed'] !== []): ?><section class="symbol-delta"><h3>Declaration delta</h3><div><?php foreach ($result['symbol_delta']['added'] as $item): ?><p><span class="delta-kind added">Added</span><strong><?= e($item['name']) ?></strong><small><?= e($item['path']) ?></small></p><?php endforeach; ?><?php foreach ($result['symbol_delta']['removed'] as $item): ?><p><span class="delta-kind removed">Removed</span><strong><?= e($item['name']) ?></strong><small><?= e($item['path']) ?></small></p><?php endforeach; ?><?php foreach ($result['symbol_delta']['changed'] as $item): ?><p><span class="delta-kind changed">Signature</span><strong><?= e($item['name']) ?></strong><small><?= e($item['path']) ?></small></p><?php endforeach; ?></div></section><?php endif; ?><?php if ($result['impact']['routes'] !== [] || $result['impact']['tables'] !== []): ?><section class="current-impact"><h3>Current graph impact</h3><?php foreach ($result['impact']['routes'] as $route): ?><p><b><?= e($route['http_method'] . ' ' . $route['route_path']) ?></b><span><?= e($route['path']) ?></span></p><?php endforeach; ?><?php foreach ($result['impact']['tables'] as $table): ?><p><b><?= e($table['symbol_type'] . ' ' . $table['name']) ?></b><span><?= e($table['path']) ?></span></p><?php endforeach; ?></section><?php endif; ?><?php foreach ($result['groups'] as $group => $changes): ?><section class="change-group"><h3><?= e($group) ?></h3><div class="change-list"><?php foreach ($changes as $change): ?><p><span class="change-status"><?= e($change['status']) ?></span><span><?= e($change['path']) ?></span><?php if ($change['risk'] !== null): ?><b><?= e($change['risk']) ?></b><?php endif; ?></p><?php endforeach; ?></div></section><?php endforeach; ?><?php if ($result['stat'] !== []): ?><details><summary>Git diff statistics</summary><pre><?= e(implode("\n", $result['stat'])) ?></pre></details><?php endif; ?></article><?php endif; ?><?php endif; ?></section></section>
<?php require __DIR__ . '/../views/footer.php'; ?>
